import java.util.*;

public class Solution {
 public String solve(String s) {
 int n = s.length();
 int[] last = new int[10];
 int[] cnt = new int[10];

 Arrays.fill(last, -1);

 // Find the last occurrence of each digit in the string
 for (int i = 0; i < n; ++i) {
 last[s.charAt(i) - '0'] = i;
 }

 StringBuilder ret = new StringBuilder();
 int left = 0;

 // Process each digit from 0 to 9
 for (int i = 0; i <= 9; ++i) {
 int m = last[i];
 // Process the string from the left until the last occurrence of current digit
 while (left <= m) {
 int j = s.charAt(left++) - '0';
 if (i == j) {
 cnt[i]++;
 } else {
 cnt[Math.min(j + 1, 9)]++;
 }
 }

 // Append the required count of current digit to the result string
 char c = (char) (i + '0');
 for (int j = 0; j < cnt[i]; ++j) {
 ret.append(c);
 }
 }

 return ret.toString();
 }

