class Solution {
 public double separateSquares(int[][] squares) {
 double totalArea = 0;
 double minY = Double.POSITIVE_INFINITY;
 double maxY = Double.NEGATIVE_INFINITY;

 for (int[] square : squares) {
 int sideLength = square[2];
 totalArea += (double) sideLength * sideLength;
 minY = Math.min(minY, square[1]);
 maxY = Math.max(maxY, square[1] + sideLength);
 }

 double targetArea = totalArea / 2;
 double epsilon = 1e-6;
 while (maxY - minY > epsilon) {
 double midY = (minY + maxY) / 2;
 double areaBelow = calculateAreaBelow(squares, midY);

 if (areaBelow < targetArea) {
 minY = midY;
 } else {
 maxY = midY;
 }
 }

 return minY;
 }

 private double calculateAreaBelow(int[][] squares, double y) {
 double areaBelow = 0;

 for (int[] square : squares) {
 int y1 = square[1];
 int sideLength = square[2];

 if (y1 + sideLength <= y) {
 areaBelow += (double) sideLength * sideLength;
 } else if (y1 < y) {
 double height = y - y1;
 areaBelow += height * sideLength;
 }
 }

 return areaBelow;
 }
}

